async function setVideoTime() {
  // Retry until the video tag is found on the DOM
  while (!document.getElementsByTagName('video')[0]) {
    await new Promise(r => setTimeout(r, 200));
  }

  // Set the position
  document.getElementsByTagName('video')[0].currentTime = 40;

  // Continue to the next Automa block
  automaNextBlock();
}

setVideoTime();;
